export function setupGalleryHelp({onQuality,stored,save}){
 const dialog=document.createElement('dialog');dialog.id='galleryHelp';dialog.innerHTML='<div class="panel"><button class="btn dialog-back" id="backHelp">← Back to gallery</button><div class="eyebrow">YOUR VISIT</div><h2>Explore at your own pace</h2><p>Drag to look around. Walk with WASD, arrow keys or the mobile control pad. Press E or click a nearby artwork, visitor or vacant bench. “Go to…” jumps between rooms.</p><p>Artwork details let you save works, read stories and leave interest without an email. Chat notifications never open a conversation automatically.</p><label class="chat-preference">VISUAL QUALITY<select id="visitorQuality"><option value="balanced">Balanced</option><option value="light">Light · reduced shadows and resolution</option></select></label><p>Quality affects this device only, not the curator’s exhibition settings.</p><p><a class="btn" href="catalogue.html">Open lightweight gallery</a> <a class="btn" href="demo.html">Leave for demo hub</a></p><p class="note">This is a presentation. Visitor avatars, chat replies and occupancy are simulated. Data stays in this browser; clearing it loses local records. There is no live artist connection or account recovery yet.</p></div>';document.body.append(dialog);const button=document.createElement('button');button.id='helpButton';button.className='pill';button.textContent='Visit guide';button.onclick=()=>dialog.showModal();document.querySelector('.hud').append(button);dialog.querySelector('#backHelp').onclick=()=>dialog.close();const quality=dialog.querySelector('#visitorQuality');quality.value=stored('anansiVisitPreferences',{}).quality==='light'?'light':'balanced';quality.onchange=()=>{save('anansiVisitPreferences',{quality:quality.value});onQuality(quality.value)};onQuality(quality.value);
}
